import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u05")
C = "A1-A2"

L(1, "As refeições do dia", "het ontbijt, de lunch, het avondeten — e a que horas.",
  ["Nomear as refeições e os seus horários"],
  vocab=[V("v-ontbijt","ontbijt","pequeno-almoço","noun","het"), V("v-lunch","lunch","almoço","noun","de"),
         V("v-tussendoortje","tussendoortje","lanche|petisco","noun","het"), V("v-maaltijd","maaltijd","refeição","noun","de","maaltijden"),
         V("v-warm-eten","warm eten","comer uma refeição quente","expression",note="Nos Países Baixos come-se quente ao jantar.")],
  ex=[("Het ontbijt is om half acht.","O pequeno-almoço é às sete e meia."),("De lunch is meestal koud.","O almoço é geralmente frio."),("We eten 's avonds warm.","Comemos (uma refeição) quente à noite.")],
  review=["v-ontbijten","v-lunchen","v-avondeten","v-broodje"],
  cefr=C, exs=[
    MA([("ontbijt","pequeno-almoço"),("lunch","almoço"),("avondeten","jantar"),("tussendoortje","lanche")], "Refeições.", ["v-ontbijt","v-lunch","v-avondeten","v-tussendoortje"]),
    AR("ontbijt","o pequeno-almoço","het", "«Het ontbijt».", ["v-ontbijt"]),
    AR("lunch","o almoço","de", "«De lunch».", ["v-lunch"]),
    AR("maaltijd","a refeição","de", "«De maaltijd».", ["v-maaltijd"]),
    MC("Em que refeição se come normalmente quente nos Países Baixos?", ["*Ao jantar","Ao almoço|O almoço costuma ser pão frio.","Ao pequeno-almoço|Normalmente pão."], "warm eten = ao jantar.", ["v-warm-eten"]),
    TR("pt-nl","O pequeno-almoço é às sete e meia.", ["Het ontbijt is om half acht"], "half acht.", ["v-ontbijt","v-half"]),
    TR("nl-pt","We eten 's avonds warm.", ["Comemos quente à noite","À noite comemos uma refeição quente"], "warm eten.", ["v-warm-eten"]),
    FB("Om tien uur eet ik een ___: een appel.", ["tussendoortje"], "Um lanche a meio da manhã.", ["v-tussendoortje"], choices=["tussendoortje","avondeten","ontbijt"], tr="Às dez como um lanche: uma maçã."),
    LI("Wat eet je bij het ontbijt?", ["Wat eet je bij het ontbijt"], "O que comes ao pequeno-almoço?", "bij het ontbijt = ao pequeno-almoço.", ["v-ontbijt"]),
    WO("O almoço é geralmente frio.", ["De","lunch","is","meestal","koud"], "meestal = geralmente.", ["v-lunch"]),
  ], diff=1, mins=5)

L(2, "À mesa: Eet smakelijk!", "Pôr a mesa, desejar bom apetite e oferecer mais.",
  ["Usar as expressões típicas à mesa"],
  vocab=[V("v-eet-smakelijk","eet smakelijk","bom apetite","expression"), V("v-tafel-dekken","de tafel dekken","pôr a mesa","expression"),
         V("v-nog","nog","mais|ainda","adverb",note="Nog een beetje? = Mais um pouco?"), V("v-genoeg","genoeg","suficiente|chega","adverb"),
         V("v-proost","proost","saúde! (brinde)","interjection")],
  ex=[("Eet smakelijk!","Bom apetite!"),("Wil je nog wat?","Queres mais um pouco?"),("Nee, dank je, ik heb genoeg gehad.","Não, obrigado, já comi o suficiente."),("Proost!","Saúde!")],
  gram=[G("g-eet-smakelijk","Expressões à mesa","Antes de comer: **Eet smakelijk!** (resposta: *Jij ook!* / *Eet smakelijk!*). Para brindar: **Proost!** Para recusar: *Nee, dank je, ik zit vol* (estou cheio) ou *ik heb genoeg gehad*.",
    [("Smakelijk!","(forma curta) Bom apetite!")])],
  review=["v-tafel","v-bord","v-glas","v-willen"],
  cefr=C, exs=[
    MA([("eet smakelijk","bom apetite"),("proost","saúde"),("genoeg","suficiente"),("nog","mais")], "À mesa.", ["v-eet-smakelijk","v-proost","v-genoeg","v-nog"]),
    DL([("Mãe","Eet smakelijk!","Bom apetite!"),("Filho","")], ["*Jij ook!","Proost!|Isso é para brindar.","Graag gedaan!|Isso é «de nada»."], "Resposta: «jij ook!» ou «eet smakelijk!».", ["v-eet-smakelijk"]),
    TR("nl-pt","Wil je nog wat?", ["Queres mais (um pouco)","Queres mais alguma coisa"], "nog wat = mais um pouco.", ["v-nog"]),
    TR("pt-nl","Não, obrigado, chega.", ["Nee(,) dank je(,) het is genoeg","Nee(,) dank je(,) ik heb genoeg"], "genoeg = suficiente.", ["v-genoeg"]),
    MC("Ao levantar o copo para brindar, diz-se…", ["*Proost!","Eet smakelijk!|Isso é «bom apetite».","Gezondheid!|Diz-se quando alguém espirra."], "Proost! = saúde!", ["v-proost"]),
    FB("Kun jij de tafel ___?", ["dekken"], "de tafel dekken = pôr a mesa.", ["v-tafel-dekken"], choices=["dekken","koken","eten"], tr="Podes pôr a mesa?"),
    LI("Nog een beetje koffie?", ["Nog een beetje koffie"], "Mais um pouco de café?", "nog = mais.", ["v-nog"]),
    EX("Ik zit vol.", "Estou sentado cheio.", "O que quer dizer quem diz isto depois de comer?", ["*Que está cheio, não quer comer mais","Que está sentado|Não é o sentido aqui.","Que tem fome|É o contrário."], "Ik zit vol = estou cheio.", ["v-genoeg"]),
    FE(["Wil","je","meer","een","beetje?"], 2, "nog", "«Mais um pouco» = nog een beetje.", ["v-nog"]),
    WO("Bom apetite a todos!", ["Eet","smakelijk","allemaal!"], "allemaal = todos.", ["v-eet-smakelijk"]),
  ], diff=2, mins=5)

L(3, "Cozinhar", "Cortar, fritar, cozer e uma receita simples.",
  ["Perceber verbos de cozinha e uma receita"],
  vocab=[V("v-snijden","snijden","cortar","verb",note="ik snijd"), V("v-bakken","bakken","fritar|cozer no forno","verb"),
         V("v-pan","pan","panela|frigideira","noun","de","pannen"), V("v-oven","oven","forno","noun","de"),
         V("v-recept","recept","receita","noun","het","recepten"), V("v-peper","peper","pimenta","noun","de")],
  ex=[("Snijd de ui.","Corta a cebola."),("Bak de eieren in de pan.","Frita os ovos na frigideira."),("Doe de pan in de oven.","Põe a panela no forno.")],
  gram=[G("g-imperativo-intro","Instruções (imperativo)","Nas receitas usa-se o **imperativo**, que é igual à **raiz** do verbo: *snijd*, *bak*, *doe*, *kook*. Fica no início da frase: *Snijd de tomaten.* (formal: *Snijdt u de tomaten*, raro em receitas).",
    [("Kook het water.","Ferve a água."),("Doe er zout bij.","Junta sal.")],
    "Em português as receitas usam muitas vezes o infinitivo («cortar a cebola»); em neerlandês, a raiz.")],
  review=["v-koken","v-ui","v-ei","v-zout","v-tomaat"],
  cefr=C, exs=[
    MA([("snijden","cortar"),("bakken","fritar"),("pan","frigideira"),("oven","forno"),("recept","receita")], "Na cozinha.", ["v-snijden","v-bakken","v-pan","v-oven","v-recept"]),
    TR("nl-pt","Snijd de ui.", ["Corta a cebola","Cortar a cebola","Corte a cebola"], "Imperativo = raiz.", ["v-snijden","v-ui"]),
    TR("pt-nl","Frita os ovos na frigideira.", ["Bak de eieren in de pan"], "bak = raiz de bakken.", ["v-bakken","v-pan"]),
    AR("recept","a receita","het", "«Het recept».", ["v-recept"]),
    CJ("snijden","ik","Ik ___ de tomaten.", ["snijd"], "snijden → ik snijd (o d escreve-se mesmo soando t).", ["v-snijden"]),
    FB("___ het water.", ["Kook"], "Imperativo de koken: kook.", ["v-koken"], choices=["Kook","Koken","Kookt"], tr="Ferve a água."),
    LI("Doe de pizza in de oven.", ["Doe de pizza in de oven"], "Põe a pizza no forno.", "doe = põe (de doen).", ["v-oven"]),
    FE(["Snijden","de","tomaten","en","de","ui."], 0, "Snijd", "Imperativo: raiz (snijd).", ["v-snijden"]),
    CO("text","Omelete simples", "Recept: omelet\n1. Breek drie eieren in een kom.\n2. Doe er zout en peper bij.\n3. Snijd een ui en een tomaat.\n4. Bak alles vijf minuten in de pan.\nEet smakelijk!",
       [("Quantos ovos são precisos?", ["*Três","Dois","Cinco"]),("Quanto tempo vai à frigideira?", ["*Cinco minutos","Três minutos","Dez minutos"])],
       "breken = partir; de kom = a tigela.", ["v-recept","v-bakken"]),
    WO("Corta o pão.", ["Snijd","het","brood"], "Imperativo no início.", ["v-snijden","v-brood"]),
  ], diff=2, mins=6)

L(4, "Comida típica neerlandesa", "stamppot, erwtensoep, stroopwafels e poffertjes.",
  ["Conhecer pratos típicos e descrevê-los"],
  vocab=[V("v-stamppot","stamppot","puré de batata com legumes","noun","de",note="Prato de inverno: batata esmagada com couve, cenoura, etc."),
         V("v-soep","soep","sopa","noun","de"), V("v-stroopwafel","stroopwafel","bolacha de caramelo","noun","de","stroopwafels"),
         V("v-patat","patat","batatas fritas","noun","de",note="No sul diz-se «friet». Clássico: patat met mayonaise."),
         V("v-typisch","typisch","típico","adjective")],
  ex=[("Stamppot is typisch Nederlands.","O stamppot é tipicamente neerlandês."),("In de winter eten we erwtensoep.","No inverno comemos sopa de ervilhas."),("Een patatje met, alstublieft.","Umas batatas fritas com maionese, por favor.")],
  gram=[G("g-cultura-comida","Cozinha neerlandesa","A cozinha tradicional é simples e de inverno: **stamppot**, **erwtensoep** (sopa espessa de ervilhas), **hutspot**. Nas ruas: **patat** (com maionese: «patatje met»), **haring** (arenque cru), **kroketten**. Doces: **stroopwafels**, **poffertjes** (minipanquecas).",
    [("Ik wil een stroopwafel proberen.","Quero provar uma stroopwafel.")])],
  review=["v-lekker","v-eten","v-aardappel","v-zoet"],
  cefr=C, exs=[
    MA([("stamppot","puré com legumes"),("soep","sopa"),("stroopwafel","bolacha de caramelo"),("patat","batatas fritas")], "Comida típica.", ["v-stamppot","v-soep","v-stroopwafel","v-patat"]),
    MC("O que é «een patatje met»?", ["*Batatas fritas com maionese","Batatas com carne|«met» aqui significa «com maionese».","Uma sopa|Não."], "patatje met = com maionese.", ["v-patat"]),
    TR("nl-pt","Stamppot is typisch Nederlands.", ["O stamppot é [tipicamente|um prato típico] neerlandês","Stamppot é típico dos Países Baixos"], "typisch = típico.", ["v-stamppot","v-typisch"]),
    TR("pt-nl","No inverno comemos sopa.", ["In de winter eten we soep","We eten in de winter soep"], "Inversão.", ["v-soep"]),
    AR("soep","a sopa","de", "«De soep».", ["v-soep"]),
    FB("Een ___ is zoet: twee dunne wafels met stroop.", ["stroopwafel"], "stroop = caramelo/xarope.", ["v-stroopwafel"], choices=["stroopwafel","stamppot","soep"], tr="Uma stroopwafel é doce: duas bolachas finas com caramelo."),
    LI("Wil je een stroopwafel proberen?", ["Wil je een stroopwafel proberen"], "Queres provar uma stroopwafel?", "proberen = provar/experimentar.", ["v-stroopwafel"]),
    CO("text","Na feira", "Op de markt in Gouda koop ik altijd verse stroopwafels. Ze zijn warm en heel lekker. Mijn vriend eet liever haring: rauwe vis met uitjes. Dat vind ik een beetje vies!",
       [("O que compra sempre a narradora?", ["*Stroopwafels frescas","Arenque","Queijo"]),("O que acha do arenque?", ["*Acha que sabe um pouco mal","Adora","Nunca provou"])],
       "rauw = cru; uitjes = cebolinhas.", ["v-stroopwafel","v-vies"]),
    WO("O stamppot é um prato de inverno.", ["Stamppot","is","een","wintergerecht"], "gerecht = prato.", ["v-stamppot"]),
    DL([("Amigo","Heb je ooit erwtensoep gegeten?","Já alguma vez comeste sopa de ervilhas?"),("Você","")], ["*Nee, nog niet. Is het lekker?","Ja, ik ben soep.|Não faz sentido.","Nee, ik heb geen soep.|Não responde."], "nog niet = ainda não.", ["v-nog-niet","v-soep"]),
  ], diff=2, mins=6)

L(5, "Um jantar em casa", "Revisão: refeições, cozinhar e expressões à mesa.",
  ["Convidar para jantar e conversar à mesa"],
  ex=[("Kom je zaterdag bij ons eten?","Vens jantar a nossa casa no sábado?")],
  review=["v-avondeten","v-koken","v-eet-smakelijk","v-nog","v-genoeg","v-lekker","v-recept","v-proost"],
  cefr=C, exs=[
    DL([("Eva","Kom je zaterdag bij ons eten?","Vens jantar connosco no sábado?"),("Pedro","")], ["*Ja, graag! Hoe laat?","Ja, ik ben eten.|Não faz sentido.","Proost!|É para brindar."], "Aceitar e perguntar a hora.", ["v-avondeten"]),
    TR("nl-pt","Het eten is klaar!", ["A comida está pronta","O jantar está pronto"], "klaar = pronto.", ["v-klaar"]),
    TR("pt-nl","Bom apetite!", ["Eet smakelijk","Smakelijk"], "Expressão fixa.", ["v-eet-smakelijk"]),
    MC("Ofereceram-lhe mais e já não quer. O que diz?", ["*Nee, dank je, ik heb genoeg gehad.","Ja, genoeg!|Contraditório.","Nee, het is vies.|Seria indelicado."], "Recusa educada.", ["v-genoeg"]),
    FE(["Wie","kookt","vanavond?","—","Ik","koken!"], 5, "kook", "ik kook.", ["v-koken"]),
    LI("Wat ruikt het hier lekker!", ["Wat ruikt het hier lekker"], "Que cheiro tão bom aqui!", "ruiken = cheirar.", ["v-lekker"]),
    CO("dialogue","O jantar", "Eva: Eet smakelijk!\nPedro: Eet smakelijk! Mmm, wat is dit lekker. Wat is het?\nEva: Stamppot boerenkool. Een typisch Nederlands recept.\nPedro: Heerlijk! Mag ik het recept?\nEva: Natuurlijk! Wil je nog wat?\nPedro: Graag, nog een beetje.",
       [("O que comem?", ["*Stamppot de couve","Sopa de ervilhas","Peixe"]),("O que pede o Pedro?", ["*A receita","Uma cerveja","A conta"]),("Quer mais?", ["*Sim, um pouco","Não, está cheio","Não gosta"])],
       "heerlijk = delicioso.", ["v-recept","v-nog"]),
    WO("Queres mais um pouco de sopa?", ["Wil","je","nog","wat","soep?"], "nog wat + nome.", ["v-nog","v-soep"]),
    MA([("Proost!","Saúde!"),("Eet smakelijk!","Bom apetite!"),("Heerlijk!","Delicioso!"),("Ik zit vol.","Estou cheio.")], "Expressões à mesa.", ["v-proost","v-eet-smakelijk"]),
    SW("Escreva uma mensagem a convidar um amigo para jantar (dia, hora, o que vai cozinhar).", ["Hoi(,) kom je [zaterdag|vrijdag] bij mij eten(?) Om [zes|zeven] uur(.) Ik kook [stamppot|vis|pasta]"],
       ["Faz o convite com «kom je … eten?»","Indica o dia e a hora","Diz o que vai cozinhar com «ik kook»"], 8, "Modelo: «Hoi Tom, kom je zaterdag bij mij eten? Om zeven uur. Ik kook vis.»", ["v-koken"]),
  ], diff=2, mins=7)

W()
